<section class="admin-panel transfers-summary"><header><h2>Ruta y seguimiento</h2><span class="transfers-status" data-state="<?= e($t['status']) ?>"><?= e(Rules::LABELS[$t['status']]) ?></span></header><div class="transfers-route"><div><small>Origen</small><strong><?= e($t['source_name']) ?></strong></div><span aria-hidden="true">→</span><div><small>Destino</small><strong><?= e($t['destination_name']) ?></strong></div></div><dl><div><dt>Motivo</dt><dd><?= e($t['reason']) ?></dd></div><div><dt>Fecha de solicitud</dt><dd><?= e($t['created_at']) ?> UTC</dd></div><div><dt>Cotización relacionada</dt><dd><?= $t['quote_version_id']===null?'Sin relación':'Versión #'.e($t['quote_version_id']) ?></dd></div></dl><p class="transfers-note">El destino aumenta su existencia cuando se confirma la recepción física. Las incidencias conservan el seguimiento sin registrar pérdidas ni entradas automáticas.</p></section>
<section class="admin-panel admin-table-panel transfers-directory"><header class="transfers-directory-heading"><div><h2>Mercancía de la transferencia</h2><p>Cantidades solicitadas, enviadas y recibidas por variante.</p></div></header><div class="admin-table-wrap" tabindex="0" role="region" aria-label="Cantidades de la transferencia"><table class="admin-table"><thead><tr><th>Mercancía</th><th>Cobertura</th><th>Solicitada</th><th>Autorizada</th><th>Despachada</th><th>Recibida</th><th>Por despachar</th><th>En tránsito</th></tr></thead><tbody><?php foreach($items as $i):$ci=$coverage[(int)$i['id']]??null;?><tr><td data-label="Mercancía"><?= e($i['sku'].' · '.$i['product_name'].' ('.$i['symbol'].')') ?></td><td data-label="Cobertura"><?= $ci===null?'Genérica':e($ci['status']==='active'?'Vigente':'Invalidada') ?></td><?php foreach(['requested_quantity'=>'Solicitada','approved_quantity'=>'Autorizada','dispatched_quantity'=>'Despachada','received_quantity'=>'Recibida','pending_dispatch'=>'Por despachar','in_transit'=>'En tránsito']as $k=>$label):?><td data-label="<?= e($label) ?>"><?= e($i[$k]) ?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div></section>
<?php $labels=['edit'=>'Editar cantidades solicitadas','approve'=>'Aprobar y apartar en origen','prepare'=>'Confirmar mercancía preparada','dispatch'=>'Confirmar salida física de origen','receive'=>'Confirmar recepción física en destino','cancel'=>'Cancelar y liberar apartado de origen','incident'=>'Registrar incidencia'];foreach($labels as $action=>$label):if(!$actions[$action])continue;if($action==='dispatch'&&!array_filter($items,fn($i)=>\App\Domain\Pricing\Decimal::parse($i['pending_dispatch'],6)->compare(\App\Domain\Pricing\Decimal::zero(6))>0))continue;if($action==='receive'&&!array_filter($items,fn($i)=>\App\Domain\Pricing\Decimal::parse($i['in_transit'],6)->compare(\App\Domain\Pricing\Decimal::zero(6))>0))continue;try{Rules::transition($t['status'],$action);}catch(Throwable){continue;} ?>
<?php if($selectedAction!==$action):?><a class="transfers-action-link" data-admin-form-link href="/admin/transfers/detail?id=<?= e($t['id']) ?>&amp;action=<?= e($action) ?>"><strong><?= e($label) ?></strong><span aria-hidden="true">→</span></a><?php continue;endif?><section class="admin-panel transfers-action-panel"><div class="admin-panel-head"><h2><?= e($label) ?></h2><a class="transfers-text-link" data-admin-form-link href="/admin/transfers/detail?id=<?= e($t['id']) ?>">Volver al detalle</a></div><form class="admin-form" method="post" action="/admin/transfers/action" data-transfer-event <?= in_array($action,['dispatch','receive','cancel'],true)?'data-transfer-confirm':'' ?>>
<input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($t['id']) ?>"><input type="hidden" name="lock_version" value="<?= e($t['lock_version']) ?>"><input type="hidden" name="action" value="<?= e($action) ?>"><input type="hidden" name="operation_key" value="<?= e(bin2hex(random_bytes(20))) ?>">
<?php if(in_array($action,['edit','approve','dispatch','receive'],true)):?><div class="admin-form-grid"><?php foreach($items as $i): $pending=match($action){'edit','approve'=>$i['requested_quantity'],'dispatch'=>$i['pending_dispatch'],default=>$i['in_transit']};?><label class="admin-field"><span><?= e($i['sku'].' · '.$i['symbol']) ?> · <?= e($action==='edit'?'Actual':'Máximo') ?> <?= e($pending) ?></span><input name="quantity[<?= e($i['id']) ?>]" inputmode="decimal" value="<?= e($action==='edit'?$pending:'0') ?>"></label><?php endforeach?></div><?php endif?>
<label class="admin-field"><span>Observaciones <?= in_array($action,['incident','cancel'],true)?'(obligatorias)':'' ?></span><textarea name="notes" maxlength="500" <?= in_array($action,['incident','cancel'],true)?'required minlength="5"':'' ?>></textarea></label>
<?php if(in_array($action,['dispatch','receive','cancel'],true)):?><label class="transfers-confirm"><input type="checkbox" required> Confirmo las cantidades y la operación <?= e($action==='dispatch'?'de salida física':($action==='receive'?'de recepción física':'de cancelación')) ?>.</label><?php endif?><button type="submit" class="admin-primary-button"><?= e($label) ?></button></form></section><?php endforeach?>
<?php if($history):?><section class="admin-panel transfers-history"><h2>Historial de la transferencia</h2><ol><?php foreach($history as $h):?><li><strong><?= e(($labels+['create'=>'Solicitud creada'])[$h['action']]??$h['action']) ?></strong> · <?= e($h['actor_name']) ?> · <?= e($h['created_at']) ?> UTC<p><?= e($h['notes']) ?> <?= e($h['quantity']??'') ?><?php if($h['inventory_movement_id']):?> · Movimiento de inventario #<?= e($h['inventory_movement_id']) ?><?php endif?></p></li><?php endforeach?></ol></section><?php endif?>
<?php if($coverageHistory):?><section class="admin-panel transfers-history"><h2>Historial de cobertura comercial</h2><ol><?php foreach($coverageHistory as $h):?><li><strong><?= e($h['action']==='linked'?'Cobertura vinculada':'Cobertura invalidada') ?></strong> · <?= e($h['actor_name']) ?> · <?= e($h['created_at']) ?> UTC<p><?= e($h['reason']) ?> · <?= e($h['quantity']) ?></p></li><?php endforeach?></ol></section><?php endif?>

